import {createAtlas,prepareRhino} from './mass-scene.js';
import {savedModels,saveModel,deleteModel} from './storage.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let atlas,city,selected=null,pending=null,buffer=null;
const status=s=>$('#import-status').textContent=s;
function photoMarkup(b){
 const p=b.photo;if(!p)return '';
 return `<figure class="building-photo"><a class="photo-link" href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(b.name)} 사진 출처 열기"><img src="${esc(p.url)}" alt="${esc(p.alt||b.name+' 외관')}" width="${p.width||800}" height="${p.height||600}" decoding="async"><span class="photo-unavailable" hidden>사진을 표시할 수 없습니다. 원본 사진 보기</span></a><figcaption>사진: ${esc(p.author)} · <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.license)}</a><span class="photo-edit-note">크기 조정 · 웹용 압축</span></figcaption></figure>`;
}
function select(id,focus=true){const b=city.landmarks.find(b=>b.id===id);if(!b)return;selected=id;atlas?.select(id,focus);const m=atlas?.measurements(id);document.body.classList.remove('detail-closed');document.querySelectorAll('[data-id]').forEach(el=>{el.classList.toggle('active',el.dataset.id===id);el.setAttribute('aria-pressed',String(el.dataset.id===id))});$('#detail').innerHTML=`<div class="detail-top"><span class="tag">${b.type}</span><button class="close-detail" aria-label="건축물 카드 닫기">×</button></div><h2>${b.name}</h2><p class="ko-name">${b.ko}</p>${photoMarkup(b)}<div class="facts"><div><span>ARCHITECT</span><strong>${b.architect}</strong></div><div><span>COMPLETION</span><strong>${b.year}</strong></div></div><div class="dimensions"><span>실제 모델 범위 · m ${m?.custom?' / MY MODEL':''}</span><strong>${m?[m.east,m.north,m.height].map(n=>n.toFixed(1)).join(' × '):'—'}</strong><small>동서 × 남북 × 높이 · ${b.massCount}개 모델 부재</small></div><p class="model-note">${esc(b.modelNote||'OSM 윤곽 기반 개략 매스. 높이 미기재 부분은 추정치입니다.')}</p><p class="point">${b.point}</p><div class="detail-links"><a href="./assets/rhino/${id}-rhino6.3dm" download>Rhino 6/7 매스 ↓</a><a href="https://www.google.com/maps/dir/?api=1&destination=${b.lat},${b.lon}&travelmode=walking" target="_blank" rel="noopener noreferrer">길찾기 ↗</a></div><div class="source-links"><a href="${b.source}" target="_blank" rel="noopener noreferrer">건축 정보 ↗</a> · <a href="${b.modelSourceUrl||'https://www.openstreetmap.org'}" target="_blank" rel="noopener noreferrer">매스 출처 ↗</a></div>`;$('#detail').scrollTop=0;const photo=$('#detail .building-photo img');if(photo)photo.onerror=()=>{photo.hidden=true;$('#detail .photo-unavailable').hidden=false};$('.close-detail').onclick=()=>document.body.classList.add('detail-closed')}
$('#city-download').onclick=()=>$('#download-dialog').showModal();$('#close-download').onclick=()=>$('#download-dialog').close();
$('#about').onclick=()=>$('#about-dialog').showModal();$('#close-about').onclick=()=>$('#about-dialog').close();
$('#import-open').onclick=()=>{$('#import-target').value=selected||'city';$('#rhino-dialog').showModal()};$('#close-import').onclick=()=>$('#rhino-dialog').close();
function clearPending(){pending?.root.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});pending=null;buffer=null;$('#apply-import').disabled=true}
async function analyze(){clearPending();const file=$('#rhino-file').files[0];if(!file)return;if(file.size>100*1024*1024){status('100 MB 이하의 .3dm 파일을 선택하세요.');return}status('파일을 분석하는 중…');$('#rhino-file').disabled=true;try{buffer=await file.arrayBuffer();pending=await prepareRhino(buffer.slice(0),$('#import-unit').value);status(`${file.name}\n${pending.objects.toLocaleString()}개 메시 · ${pending.triangles.toLocaleString()} 삼각형\n${Object.values(pending.size).map(n=>n.toFixed(2)).join(' × ')} m (동서 × 남북 × 높이)${pending.warnings?'\n일부 객체는 읽지 못했습니다. 메시로 변환해 저장하면 더 정확합니다.':''}`);$('#apply-import').disabled=false}catch(e){status('불러오기 실패: '+e.message)}finally{$('#rhino-file').disabled=false}}
$('#rhino-file').onchange=analyze;$('#import-unit').onchange=analyze;
$('#apply-import').onclick=async()=>{if(!pending)return;const key=$('#import-target').value;if(key!=='city'){const center=pending.bounds.getCenter(pending.root.position.clone());if(Math.hypot(center.x,center.z)>2000){status('건축물 파일 원점이 멀리 있습니다. 전체 도시 파일이면 적용 대상을 전체 도시로 선택하세요. 개별 모델은 제공된 로컬 원점을 유지하세요.');return}}const item={key,buffer,name:$('#rhino-file').files[0].name,unit:$('#import-unit').value};atlas.applyImport(pending,key);pending=null;$('#apply-import').disabled=true;try{await saveModel(item);status('적용 완료 · 이 브라우저에 저장했습니다.')}catch{status('적용 완료 · 저장 공간 부족으로 새로고침 후 유지되지 않습니다.')}if(selected)select(selected,false)};
$('#restore-model').onclick=async()=>{const key=$('#import-target').value;atlas.restore(key);try{await deleteModel(key);status('원본 매스로 복원했습니다.')}catch{status('화면은 복원했지만 브라우저 저장 데이터 삭제에 실패했습니다.')}if(selected)select(selected,false)};
try{
const response=await fetch('./assets/city.json');if(!response.ok)throw Error('도시 데이터 로드 실패');city=await response.json();$('#count').textContent=city.landmarks.length;
$('#mass-count').textContent=city.stats.masses.toLocaleString()+'개의 3D 매스.';
$('#height-stats').textContent=`${city.stats.masses.toLocaleString()}개 매스 중 OSM 높이 ${city.stats.heights.height.toLocaleString()}개, 층수 추정 ${city.stats.heights.levels.toLocaleString()}개, 높이 미기재 ${city.stats.heights.assumed.toLocaleString()}개입니다.`;
for(const file of city.rhinoDownloads||[]){const link=document.createElement('a');link.href=file.url;link.download='';link.className='region-download';link.textContent=`${file.name} · ${file.masses.toLocaleString()} 매스 · ${(file.bytes/1048576).toFixed(1)} MB ↓`;$('#region-downloads').append(link)}

for(const [i,b]of city.landmarks.entries()){const el=document.createElement('button');el.className='building-item';el.dataset.id=b.id;el.innerHTML=`<span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${b.name}</strong><small>${b.ko}</small></span><span class="arrow">↗</span>`;el.onclick=()=>select(b.id);$('#buildings').append(el);const option=document.createElement('option');option.value=b.id;option.textContent=b.name;$('#import-target').append(option)}
atlas=await createAtlas(city,id=>select(id,false));$('#zoom-in').onclick=()=>atlas.zoom(1.25);$('#zoom-out').onclick=()=>atlas.zoom(.8);$('#reset').onclick=()=>{atlas.reset();document.body.classList.add('detail-closed')};$('#show-context').onchange=e=>atlas.setContext(e.target.checked);$('#show-confidence').onchange=e=>{atlas.setConfidence(e.target.checked);$('#confidence-legend').hidden=!e.target.checked};
$('#import-open').disabled=false;try{const models=await savedModels();models.sort((a,b)=>(b.key==='city')-(a.key==='city'));for(const item of models){try{atlas.applyImport(await prepareRhino(item.buffer.slice(0),item.unit),item.key)}catch(e){status(`${item.name} 자동 복원 실패: ${e.message}`)}}}catch(e){status('브라우저 저장소를 사용할 수 없습니다. 불러온 모델은 현재 화면에서만 유지됩니다.')}
$('#loading').hidden=true;document.body.classList.add('detail-closed');
}catch(e){console.error(e);$('#loading').hidden=true;$('#error').hidden=false;$('#error').textContent='3D 지도 로드 실패: '+e.message}
